head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > E > onremoverow]<br/>DataList 모듈에서 Row 가 '제거' 되면 발생합니다.",
    "validation" : [
        "DataList 모듈에서 Row 가 '제거' 되면 발생합니다.",
        "여러 건의 Row 를 한 번에 '제거' 해도 onremoverow 이벤트는 한 번만 발생합니다.",
        "info 파라미터로 'removedDataObj' Key 에 '제거' 된 Row 의 정보가 설정된 JSON 형식의 객체로 전달됩니다.",
        "info.removedDataObj '제거' 된 Row 데이터의 인덱스값을 Key 로 '제거' 된 Row 데이터가 설정된 JSON 형식의 객체를 갖습니다.",
        "{removedDataObj: {'Row 인덱스값': 'Row 데이터'}, {'Row 인덱스값': 'Row 데이터'},...} 형식의 Key-Value 쌍으로 구성됩니다.",
        "'Row 인덱스값' Key 는 필터/정렬이 적용된 상태를 기준으로 '제거' 된 Row 의 인덱스값이 설정됩니다.",
        "removeAll() 과 같이 필터/정렬이 해제된 상태로 실행되는 메소드로 '제거' 된 경우 원본(Origin) Row 의 인덱스값이 설정됩니다.",
        "'Row 데이터' 는 '제거' 된 Row 의 데이터를 1차원 배열로 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩    
    target1.bind("onremoverow", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onremoverow=====");

        let jsonString = JSON.stringify(info);

        wf_body_bottom.getObj("scwin").setReturnValue("removedDataObj: " + jsonString);   
    });      

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    isFilter = false;
    isSort = false;
}   



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow();
};



scwin.btn_insertRow_onclick = function (e) {
    target1.insertRow();
};



scwin.btn_setData_onclick = function (e) {     
    target1.setData(["setcol1","setcol2","setcol3","setcol4", "setcol5","setcol6","setcol7","setcol8"]);
};



scwin.btn_modifyAllStatus_onclick = function (e) {
    target1.modifyAllStatus("U");
};



scwin.btn_deleteRows_onclick = function (e) {
    target1.deleteRows([0, 1]);
};



scwin.btn_removeRows_onclick = function (e) {
	target1.removeRows([0, 1]);
};



scwin.btn_removeAll_onclick = function (e) {
    target1.removeAll();
};



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})             
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})             
        isFilter = true;
    }	
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }
}
